import * as fs from 'fs';

const logPath = '<tmp>';
const content = fs.readFileSync(logPath, 'utf-8');
const lines = content.split('\n').filter(line => line.trim() !== '');

const levelRegex = /^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.+)$/;

const levelCounts: Map<string, number> = new Map();
const componentErrorCounts: Map<string, number> = new Map();
const errorMessages: Set<string> = new Set();
const hourCounts: Map<string, number> = new Map();

for (const line of lines) {
  const match = line.match(levelRegex);
  if (!match) continue;

  const [, timestamp, level, component, message] = match;

  levelCounts.set(level, (levelCounts.get(level) || 0) + 1);

  if (level === 'ERROR') {
    componentErrorCounts.set(component, (componentErrorCounts.get(component) || 0) + 1);
    errorMessages.add(message);
  }

  const hour = timestamp.split(' ')[1].substring(0, 2);
  hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);
}

const out: string[] = [];
out.push('=== Log Analysis ===');
out.push('');

out.push('Entries by Level:');
const sortedLevels = [...levelCounts.entries()].sort((a, b) => a[0].localeCompare(b[0]));
for (const [level, count] of sortedLevels) {
  out.push(`  ${level}: ${count}`);
}

out.push('');

let maxErrorComponent = '';
let maxErrorCount = 0;
for (const [comp, count] of componentErrorCounts) {
  if (count > maxErrorCount || (count === maxErrorCount && comp < maxErrorComponent)) {
    maxErrorCount = count;
    maxErrorComponent = comp;
  }
}
out.push(`Component with Most Errors: ${maxErrorComponent} (${maxErrorCount} errors)`);

out.push('');

out.push('Unique Error Messages:');
const sortedMessages = [...errorMessages].sort();
for (const msg of sortedMessages) {
  out.push(`  - ${msg}`);
}

out.push('');

let busiestHour = '';
let busiestCount = 0;
for (const [hour, count] of hourCounts) {
  if (count > busiestCount || (count === busiestCount && hour < busiestHour)) {
    busiestCount = count;
    busiestHour = hour;
  }
}
out.push(`Busiest Hour: ${busiestHour}:00 (${busiestCount} entries)`);

process.stdout.write(out.join('\n') + '\n');

