import * as fs from 'fs';

function formatWithCommas(n: number, decimals: number = 0): string {
    const fixed = n.toFixed(decimals);
    const negative = fixed.startsWith('-');
    const abs = negative ? fixed.slice(1) : fixed;
    const [intPart, decPart] = abs.split('.');
    const intFormatted = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    const result = (negative ? '-' : '') + intFormatted + (decPart ? '.' + decPart : '');
    return result;
}

const csvPath = '<tmp>';
const csv = fs.readFileSync(csvPath, 'utf-8');
const lines = csv.split(/\r?\n/).filter(l => l.trim() !== '');
const header = lines[0].split(',').map(h => h.trim());
const idx: Record<string, number> = {};
header.forEach((h, i) => { idx[h] = i; });

interface Employee {
    employee_id: string;
    name: string;
    department: string;
    salary: number;
    start_date: string;
    rating: string;
}

const employees: Employee[] = lines.slice(1).map(line => {
    const cols = line.split(',').map(c => c.trim());
    return {
        employee_id: cols[idx['employee_id']],
        name: cols[idx['name']],
        department: cols[idx['department']],
        salary: parseFloat(cols[idx['salary']]),
        start_date: cols[idx['start_date']],
        rating: cols[idx['rating']]
    };
});

const deptSalaries: Map<string, number[]> = new Map();
for (const emp of employees) {
    if (!deptSalaries.has(emp.department)) {
        deptSalaries.set(emp.department, []);
    }
    deptSalaries.get(emp.department)!.push(emp.salary);
}

const sortedDepts = [...deptSalaries.keys()].sort();

const highestPaid = employees.reduce((max, emp) => emp.salary > max.salary ? emp : max, employees[0]);

const deptCounts: Map<string, number> = new Map();
for (const emp of employees) {
    deptCounts.set(emp.department, (deptCounts.get(emp.department) || 0) + 1);
}

const deptsOver2 = [...deptCounts.entries()]
    .filter(([_, count]) => count > 2)
    .sort(([a], [b]) => a.localeCompare(b));

const totalBudget = Math.round(employees.reduce((sum, emp) => sum + emp.salary, 0));

const out: string[] = [];
out.push('=== Salary Report ===');
out.push('');
out.push('Average Salary by Department:');
for (const dept of sortedDepts) {
    const salaries = deptSalaries.get(dept)!;
    const avg = salaries.reduce((a, b) => a + b, 0) / salaries.length;
    out.push(`  ${dept}: $${formatWithCommas(avg, 2)}`);
}
out.push('');
out.push(`Highest Paid: ${highestPaid.name} ($${formatWithCommas(Math.round(highestPaid.salary))})`);
out.push('');
out.push('Departments with >2 employees:');
for (const [dept, count] of deptsOver2) {
    out.push(`  ${dept} (${count} employees)`);
}
out.push('');
out.push(`Total Budget: $${formatWithCommas(totalBudget)}`);

process.stdout.write(out.join('\n') + '\n');

