                topComponent = e.getKey();
            }
        }
        sb.append("Component with Most Errors: ").append(topComponent).append(" (").append(maxErrors).append(" errors)\n");
        sb.append("\n");
        sb.append("Unique Error Messages:\n");
        for (String msg : errorMessages) {
            sb.append("  - ").append(msg).append("\n");
        }
        sb.append("\n");
        String topHour = "";
        int maxEntries = 0;
        for (Map.Entry<String, Integer> e : hourCounts.entrySet()) {
            if (e.getValue() > maxEntries) {
                maxEntries = e.getValue();
                topHour = e.getKey();
            }
        }
        sb.append("Busiest Hour: ").append(topHour).append(":00 (").append(maxEntries).append(" entries)\n");

