use std::collections::HashMap;
use std::fs;

fn format_number(value: f64, decimals: usize) -> String {
    let negative = value < 0.0;
    let value = value.abs();

    let int_part = value as i64;
    let dec_part = if decimals > 0 {
        let scale = 10_f64.powi(decimals as i32);
        ((value - int_part as f64) * scale).round() as i64
    } else {
        0
    };

    let int_str = int_part.to_string();
    let mut result = String::new();
    let len = int_str.len();
    for (i, c) in int_str.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }

    if decimals > 0 {
        result.push('.');
        let dec_str = format!("{:0width$}", dec_part, width = decimals);
        result.push_str(&dec_str);
    }

    if negative {
        result = format!("-{}", result);
    }

    result
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read CSV file");

    let mut lines = content.lines();
    let _header = lines.next();

    let mut dept_salaries: HashMap<String, Vec<f64>> = HashMap::new();
    let mut highest_salary: f64 = f64::MIN;
    let mut highest_name = String::new();
    let mut total_budget: f64 = 0.0;

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').map(|s| s.trim()).collect();
        if fields.len() < 6 {
            continue;
        }

        let name = fields[1].to_string();
        let department = fields[2].to_string();
        let salary: f64 = fields[3].parse().unwrap_or(0.0);

        dept_salaries.entry(department).or_insert_with(Vec::new).push(salary);
        total_budget += salary;

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name;
        }
    }

    let mut depts: Vec<&String> = dept_salaries.keys().collect();
    depts.sort();

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for dept in &depts {
        let salaries = &dept_salaries[*dept];
        let avg = salaries.iter().sum::<f64>() / salaries.len() as f64;
        println!("  {}: ${}", dept, format_number(avg, 2));
    }
    println!();
    println!("Highest Paid: {} (${})", highest_name, format_number(highest_salary, 0));
    println!();
    println!("Departments with >2 employees:");
    for dept in &depts {
        let count = dept_salaries[*dept].len();
        if count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!();
    println!("Total Budget: ${}", format_number(total_budget, 0));
}

