use std::fs;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut component_errors: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: BTreeMap<u32, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let close_bracket = line.find(']').expect("No closing bracket");
        let timestamp = &line[1..close_bracket]; // "YYYY-MM-DD HH:MM:SS"

        let rest = &line[close_bracket + 1..]; // " LEVEL (component) - message"
        let rest = rest.trim_start(); // "LEVEL (component) - message"

        let paren_pos = rest.find('(').expect("No opening paren");
        let level = rest[..paren_pos].trim().to_string();

        let close_paren = rest.find(')').expect("No closing paren");
        let component = &rest[paren_pos + 1..close_paren];

        let after_component = &rest[close_paren + 1..]; // " - message"
        let after_component_trimmed = after_component.trim_start();
        let message = if after_component_trimmed.starts_with("- ") {
            after_component_trimmed[2..].to_string()
        } else {
            after_component_trimmed.to_string()
        };

        // Count by level
        *level_counts.entry(level.clone()).or_insert(0) += 1;

        // Extract hour from "YYYY-MM-DD HH:MM:SS" -> positions 11..13
        let hour: u32 = timestamp[11..13].parse().expect("Invalid hour");
        *hour_counts.entry(hour).or_insert(0) += 1;

        // Track errors
        if level == "ERROR" {
            *component_errors.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message);
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (top_component, top_count) = component_errors
        .iter()
        .max_by_key(|(_, c)| *c)
        .expect("No errors found");
    println!("Component with Most Errors: {} ({} errors)", top_component, top_count);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = hour_counts
        .iter()
        .max_by_key(|(_, c)| *c)
        .expect("No entries");
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, busiest_count);
}

