declare const require: (id: string) => any;
declare const process: { exit(code?: number): never };

interface Product {
  id: number;
  name: string;
  price: number;
  category: string;
  stock: number;
}

const http = require('http');

const req = http.get('http://127.0.0.1:18923/api/products', (res: any) => {
  let data = '';
  res.on('data', (chunk: string) => {
    data += chunk;
  });
  res.on('end', () => {
    const products: Product[] = JSON.parse(data);
    const filtered = products.filter((p: Product) => p.price > 50.00);
    filtered.sort((a: Product, b: Product) => a.name.localeCompare(b.name));

    console.log('=== Filtered Products (price > $50.00) ===');
    console.log('');
    for (const p of filtered) {
      console.log(`${p.name}: $${p.price.toFixed(2)}`);
    }
    console.log('');
    console.log(`Count: ${filtered.length}`);
    console.log(`Total: $${filtered.reduce((sum: number, p: Product) => sum + p.price, 0).toFixed(2)}`);
  });
});

req.on('error', (err: Error) => {
  console.error(err);
  process.exit(1);
});

