import Foundation

let path = "<tmp>"
let data = try! Data(contentsOf: URL(fileURLWithPath: path))
let json = try! JSONSerialization.jsonObject(with: data) as! [String: Any]

let nodes = json["nodes"] as! [String]
let edges = json["edges"] as! [[String: Any]]

var adj: [String: [(String, Int)]] = [:]
for node in nodes {
    adj[node] = []
}
for edge in edges {
    let from = edge["from"] as! String
    let to = edge["to"] as! String
    let weight: Int
    if let i = edge["weight"] as? Int {
        weight = i
    } else if let d = edge["weight"] as? Double {
        weight = Int(d)
    } else {
        weight = 0
    }
    adj[from]?.append((to, weight))
    adj[to]?.append((from, weight))
}

let start = "A"
var dist: [String: Int] = [:]
var visited: Set<String> = []

for node in nodes {
    dist[node] = Int.max
}
dist[start] = 0

var pq: [(Int, String)] = [(0, start)]

while !pq.isEmpty {
    let minIdx = pq.indices.min { pq[$0].0 < pq[$1].0 }!
    let (d, u) = pq.remove(at: minIdx)
    if visited.contains(u) { continue }
    visited.insert(u)
    if let neighbors = adj[u] {
        for (v, w) in neighbors {
            if !visited.contains(v) {
                let newDist = d + w
                if newDist < (dist[v] ?? Int.max) {
                    dist[v] = newDist
                    pq.append((newDist, v))
                }
            }
        }
    }
}

print("=== Shortest Paths from A ===")
print("")
let sorted = nodes.sorted()
for node in sorted {
    let d = dist[node] ?? 0
    print("A -> \(node): \(d)")
}

