import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class Main {

    static final String PATH_A = "<tmp>";
    static final String PATH_B = "<tmp>";

    static class Parser {
        private final String s;
        private int i = 0;

        Parser(String s) {
            this.s = s;
        }

        Object parse() {
            Object v = value();
            skipWs();
            if (i < s.length()) {
                throw new RuntimeException("Trailing content in JSON");
            }
            return v;
        }

        private void skipWs() {
            while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++;
        }

        private Object value() {
            skipWs();
            if (i >= s.length()) throw new RuntimeException("Unexpected end of JSON");
            char c = s.charAt(i);
            if (c == '{') return object();
            if (c == '[') return array();
            if (c == '"') return string();
            if (c == 't' || c == 'f') return bool();
            if (c == 'n') {
                expect("null");
                return null;
            }
            return number();
        }

        private Map<String, Object> object() {
            Map<String, Object> m = new LinkedHashMap<>();
            i++; // {
            skipWs();
            if (s.charAt(i) == '}') {
                i++;
                return m;
            }
            while (true) {
                skipWs();
                String k = string();
                skipWs();
                if (s.charAt(i) != ':') throw new RuntimeException("Expected ':' in object");
                i++;
                Object v = value();
                m.put(k, v);
                skipWs();
                char c = s.charAt(i);
                if (c == ',') {
                    i++;
                    continue;
                }
                if (c == '}') {
                    i++;
                    break;
                }
                throw new RuntimeException("Expected ',' or '}' in object");
            }
            return m;
        }

        private List<Object> array() {
            List<Object> l = new ArrayList<>();
            i++; // [
            skipWs();
            if (s.charAt(i) == ']') {
                i++;
                return l;
            }
            while (true) {
                l.add(value());
                skipWs();
                char c = s.charAt(i);
                if (c == ',') {
                    i++;
                    continue;
                }
                if (c == ']') {
                    i++;
                    break;
                }
                throw new RuntimeException("Expected ',' or ']' in array");
            }
            return l;
        }

        private String string() {
            if (s.charAt(i) != '"') throw new RuntimeException("Expected string");
            i++;
            StringBuilder sb = new StringBuilder();
            while (true) {
                char c = s.charAt(i++);
                if (c == '"') break;
                if (c == '\\') {
                    char e = s.charAt(i++);
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            sb.append((char) Integer.parseInt(s.substring(i, i + 4), 16));
                            i += 4;
                            break;
                        default:
                            throw new RuntimeException("Invalid escape: \\" + e);
                    }
                } else {
                    sb.append(c);
                }
            }
            return sb.toString();
        }

        private Object bool() {
            if (s.startsWith("true", i)) {
                i += 4;
                return Boolean.TRUE;
            }
            if (s.startsWith("false", i)) {
                i += 5;
                return Boolean.FALSE;
            }
            throw new RuntimeException("Invalid literal");
        }

        private void expect(String lit) {
            if (!s.startsWith(lit, i)) throw new RuntimeException("Invalid literal, expected " + lit);
            i += lit.length();
        }

        private Object number() {
            int start = i;
            while (i < s.length()) {
                char c = s.charAt(i);
                if (Character.isDigit(c) || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E') i++;
                else break;
            }
            String tok = s.substring(start, i);
            if (tok.isEmpty()) throw new RuntimeException("Invalid number");
            if (tok.contains(".") || tok.contains("e") || tok.contains("E")) {
                return (Object) Double.parseDouble(tok);
            }
            try {
                return (Object) Long.parseLong(tok);
            } catch (NumberFormatException e) {
                return (Object) Double.parseDouble(tok);
            }
        }
    }

    static Object merge(Object a, Object b) {
        if (a instanceof Map && b instanceof Map) {
            Map<String, Object> ra = (Map<String, Object>) a;
            Map<String, Object> rb = (Map<String, Object>) b;
            Map<String, Object> r = new LinkedHashMap<>();
            for (Map.Entry<String, Object> e : ra.entrySet()) {
                r.put(e.getKey(), e.getValue());
            }
            for (Map.Entry<String, Object> e : rb.entrySet()) {
                if (r.containsKey(e.getKey())) {
                    r.put(e.getKey(), merge(r.get(e.getKey()), e.getValue()));
                } else {
                    r.put(e.getKey(), e.getValue());
                }
            }
            return r;
        }
        if (a instanceof List && b instanceof List) {
            List<Object> la = (List<Object>) a;
            List<Object> lb = (List<Object>) b;
            List<Object> r = new ArrayList<>(la);
            Set<String> seen = new HashSet<>();
            for (Object o : la) seen.add(canon(o));
            for (Object o : lb) {
                String c = canon(o);
                if (!seen.contains(c)) {
                    seen.add(c);
                    r.add(o);
                }
            }
            return r;
        }
        // Scalar conflict or type mismatch: B overrides A
        return b;
    }

    static String canon(Object o) {
        StringBuilder sb = new StringBuilder();
        write(o, sb, false, 0);
        return sb.toString();
    }

    static void write(Object o, StringBuilder sb, boolean pretty, int depth) {
        if (o == null) {
            sb.append("null");
            return;
        }
        if (o instanceof Boolean) {
            sb.append(o.toString());
            return;
        }
        if (o instanceof Long) {
            sb.append(o.toString());
            return;
        }
        if (o instanceof Double) {
            double d = (Double) o;
            if (d == Math.floor(d) && !Double.isInfinite(d) && Math.abs(d) < 1e15) {
                sb.append((long) d);
            } else {
                sb.append(Double.toString(d));
            }
            return;
        }
        if (o instanceof String) {
            writeString((String) o, sb);
            return;
        }
        if (o instanceof List) {
            List<?> l = (List<?>) o;
            if (l.isEmpty()) {
                sb.append("[]");
                return;
            }
            if (pretty) {
                sb.append("[\n");
            } else {
                sb.append('[');
            }
            for (int k = 0; k < l.size(); k++) {
                if (pretty) indent(sb, depth + 1);
                write(l.get(k), sb, pretty, depth + 1);
                if (k < l.size() - 1) {
                    sb.append(pretty ? ",\n" : ",");
                } else if (pretty) {
                    sb.append('\n');
                }
            }
            if (pretty) indent(sb, depth);
            sb.append(']');
            return;
        }
        if (o instanceof Map) {
            Map<?, ?> m = (Map<?, ?>) o;
            if (m.isEmpty()) {
                sb.append("{}");
                return;
            }
            List<String> keys = new ArrayList<>();
            for (Object k : m.keySet()) keys.add((String) k);
            Collections.sort(keys);
            if (pretty) {
                sb.append("{\n");
            } else {
                sb.append('{');
            }
            for (int k = 0; k < keys.size(); k++) {
                if (pretty) indent(sb, depth + 1);
                writeString(keys.get(k), sb);
                sb.append(pretty ? ": " : ":");
                write(m.get(keys.get(k)), sb, pretty, depth + 1);
                if (k < keys.size() - 1) {
                    sb.append(pretty ? ",\n" : ",");
                } else if (pretty) {
                    sb.append('\n');
                }
            }
            if (pretty) indent(sb, depth);
