public class Main {
    public static void main(String[] args) throws Exception {
        String path = "<tmp>";
        String json = readFile(path);

        List<String> nodes = parseNodes(json);
        List<String> edgeFrom = new ArrayList<>();
        List<String> edgeTo = new ArrayList<>();
        List<Integer> edgeWeight = new ArrayList<>();
        parseEdges(json, edgeFrom, edgeTo, edgeWeight);

        Map<String, Integer> nodeIndex = new HashMap<>();
        for (int i = 0; i < nodes.size(); i++) nodeIndex.put(nodes.get(i), i);

        Map<String, List<String[]>> adj = new HashMap<>();
        for (String n : nodes) adj.put(n, new ArrayList<>());

        for (int i = 0; i < edgeFrom.size(); i++) {
            String from = edgeFrom.get(i);
            String to = edgeTo.get(i);
            int w = edgeWeight.get(i);
            if (adj.containsKey(from)) adj.get(from).add(new String[]{to, String.valueOf(w)});
            if (adj.containsKey(to)) adj.get(to).add(new String[]{from, String.valueOf(w)});
        }

        Map<String, Integer> dist = new HashMap<>();
        for (String n : nodes) dist.put(n, Integer.MAX_VALUE);
        dist.put("A", 0);

        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.add(new long[]{0, nodeIndex.get("A")});

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int d = (int) cur[0];
            int idx = (int) cur[1];
            String node = nodes.get(idx);

            if (d > dist.get(node)) continue;

            for (String[] edge : adj.get(node)) {
                String neighbor = edge[0];
                int w = Integer.parseInt(edge[1]);
                int newDist = d + w;
                if (newDist < dist.get(neighbor)) {
                    dist.put(neighbor, newDist);
                    pq.add(new long[]{newDist, nodeIndex.get(neighbor)});
                }
            }
        }

        List<String> sorted = new ArrayList<>(nodes);
        Collections.sort(sorted);

        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        for (String n : sorted) {
            System.out.println("A -> " + n + ": " + dist.get(n));
        }
    }

