                sb.append(line).append("\n");
            }
        }
        return sb.toString();
    }

    private static List<String> parseNodes(String json) {
        List<String> nodes = new ArrayList<>();
        int start = json.indexOf("\"nodes\"");
        start = json.indexOf('[', start);
        int depth = 0;
        int end = start;
        for (int i = start; i < json.length(); i++) {
            if (json.charAt(i) == '[') depth++;
            else if (json.charAt(i) == ']') {
                depth--;
                if (depth == 0) { end = i; break; }
            }
        }
        String arr = json.substring(start + 1, end);
        int i = 0;
        while (i < arr.length()) {
            if (arr.charAt(i) == '"') {
                int j = i + 1;
                while (j < arr.length() && arr.charAt(j) != '"') {
                    if (arr.charAt(j) == '\\') j++;
                    j++;
                }
                nodes.add(arr.substring(i + 1, j));
                i = j + 1;
            } else {
                i++;
            }
        }
        return nodes;
    }

    private static void parseEdges(String json, List<String> froms, List<String> tos, List<Integer> weights) {
        int start = json.indexOf("\"edges\"");
        start = json.indexOf('[', start);
        int depth = 0;
        int end = start;
        for (int i = start; i < json.length(); i++) {
            if (json.charAt(i) == '[') depth++;
            else if (json.charAt(i) == ']') {
                depth--;
                if (depth == 0) { end = i; break; }
            }
        }
        String arr = json.substring(start + 1, end);

        int i = 0;
        while (i < arr.length()) {
            if (arr.charAt(i) == '{') {
                int j = i + 1;
                int depth2 = 1;
                while (j < arr.length() && depth2 > 0) {
                    if (arr.charAt(j) == '{') depth2++;
                    else if (arr.charAt(j) == '}') depth2--;
                    j++;
                }
                String obj = arr.substring(i + 1, j - 1);
                String from = extractString(obj, "from");
                String to = extractString(obj, "to");
                int weight = extractInt(obj, "weight");
                froms.add(from);
                tos.add(to);
                weights.add(weight);
                i = j;
            } else {
                i++;
            }
        }
    }

    private static String extractString(String obj, String key) {
        int idx = obj.indexOf("\"" + key + "\"");
        idx = obj.indexOf(':', idx);
        idx = obj.indexOf('"', idx);
        int end = obj.indexOf('"', idx + 1);
        return obj.substring(idx + 1, end);
    }

    private static int extractInt(String obj, String key) {
        int idx = obj.indexOf("\"" + key + "\"");
        idx = obj.indexOf(':', idx);
        idx++;
        while (idx < obj.length() && (obj.charAt(idx) == ' ' || obj.charAt(idx) == '\t')) idx++;
        int end = idx;
        while (end < obj.length() && (Character.isDigit(obj.charAt(end)) || obj.charAt(end) == '-')) end++;
        return Integer.parseInt(obj.substring(idx, end).trim());
    }
