import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class FileInfo {
        String relPath;
        long lines;
        long chars;
        FileInfo(String relPath, long lines, long chars) {
            this.relPath = relPath;
            this.lines = lines;
            this.chars = chars;
        }
    }

    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");

        List<Path> files = new ArrayList<>();
        walkDirectory(root, files);

        Map<String, List<FileInfo>> byExtension = new TreeMap<>();

        for (Path file : files) {
            String fileName = file.getFileName().toString();
            String ext = getExtension(fileName);
            long lines = countLines(file);
            long chars = Files.size(file);
            String relPath = root.relativize(file).toString().replace('\\', '/');
            byExtension.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileInfo(relPath, lines, chars));
        }

        for (List<FileInfo> list : byExtension.values()) {
            list.sort(Comparator.comparing(f -> f.relPath));
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<FileInfo>> entry : byExtension.entrySet()) {
            String ext = entry.getKey();
            List<FileInfo> flist = entry.getValue();

            long extLines = 0;
            long extChars = 0;
            for (FileInfo f : flist) {
                extLines += f.lines;
                extChars += f.chars;
            }

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(flist.size()).append("\n");
            sb.append("  Total Lines: ").append(extLines).append("\n");
            sb.append("  Total Characters: ").append(extChars).append("\n");

            for (FileInfo f : flist) {
