import Foundation

let baseDir = "<tmp>"
let fm = FileManager.default

struct FileStats {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var allFiles: [String: [FileStats]] = [:]

func walkDirectory(_ path: String, basePath: String) {
    let contents = (try? fm.contentsOfDirectory(atPath: path)) ?? []
    for name in contents {
        let fullPath = path + "/" + name
        let attrs = (try? fm.attributesOfItem(atPath: fullPath)) ?? [:]
        let fileType = attrs[.type] as? String ?? ""

        if fileType == "NSFileTypeSymbolicLink" {
            continue
        }

        if fileType == "NSFileTypeDirectory" {
            walkDirectory(fullPath, basePath: basePath)
        } else if fileType == "NSFileTypeRegular" {
            let relativePath = String(fullPath.dropFirst(basePath.count + 1))

            let data = (try? Data(contentsOf: URL(fileURLWithPath: fullPath))) ?? Data()
            let charCount = data.count

            let newlineCount = data.reduce(0) { $0 + ($1 == 0x0A ? 1 : 0) }
            var lineCount: Int
            if data.isEmpty {
                lineCount = 0
            } else {
                let endsWithNewline = data.last == 0x0A
                lineCount = endsWithNewline ? newlineCount : newlineCount + 1
            }

            let ext = (fullPath as NSString).pathExtension
            let extKey = ext.isEmpty ? "(no extension)" : "." + ext

            let stats = FileStats(relativePath: relativePath, lines: lineCount, chars: charCount)
            allFiles[extKey, default: []].append(stats)
        }
    }
}

