#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *run_command(const char *cmd) {
    FILE *f = popen(cmd, "r");
    if (!f) return NULL;

    size_t cap = 4096;
    char *buf = (char *)malloc(cap);
    if (!buf) {
        pclose(f);
        return NULL;
    }

    size_t len = 0;
    int c;
    while ((c = fgetc(f)) != EOF) {
        if (len + 2 >= cap) {
            cap *= 2;
            char *tmp = (char *)realloc(buf, cap);
            if (!tmp) {
                free(buf);
                pclose(f);
                return NULL;
            }
            buf = tmp;
        }
        buf[len++] = (char)c;
    }
    pclose(f);
    buf[len] = '\0';

    while (len > 0 &&
           (buf[len - 1] == '\n' || buf[len - 1] == '\r' ||
            buf[len - 1] == ' '  || buf[len - 1] == '\t')) {
        buf[--len] = '\0';
    }

    return buf;
}

