import * as fs from 'fs';
import * as path from 'path';

const ROOT = '<tmp>';

interface FileInfo {
  relPath: string;
  lines: number;
  chars: number;
}

function walk(dir: string, root: string): FileInfo[] {
  const results: FileInfo[] = [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isDirectory()) {
      results.push(...walk(fullPath, root));
    } else if (entry.isFile()) {
      const relPath = path.relative(root, fullPath).split(path.sep).join('/');
      const stat = fs.statSync(fullPath);
      const chars: number = stat.size;
      let lines: number;
      if (chars === 0) {
        lines = 0;
      } else {
        const content = fs.readFileSync(fullPath, 'utf-8');
        const parts = content.split('\n');
        if (parts[parts.length - 1] === '') {
          parts.pop();
        }
        lines = parts.length;
      }
      results.push({ relPath, lines, chars });
    }
  }

  return results;
}

function main(): void {
  const allFiles: FileInfo[] = walk(ROOT, ROOT);

  const groups = new Map<string, FileInfo[]>();
  for (const file of allFiles) {
    const ext = path.extname(file.relPath);
    if (!groups.has(ext)) {
      groups.set(ext, []);
    }
    groups.get(ext)!.push(file);
  }

  const sortedExts: string[] = Array.from(groups.keys()).sort();

  for (const ext of sortedExts) {
    groups.get(ext)!.sort((a, b) => a.relPath < b.relPath ? -1 : a.relPath > b.relPath ? 1 : 0);
  }

  const out: string[] = [];
  out.push('=== File Tree Analysis ===');
  out.push('');

  let totalFiles = 0;
  let totalLines = 0;
  let totalChars = 0;

  for (const ext of sortedExts) {
    const files = groups.get(ext)!;
    const fileCount = files.length;
    const lineSum = files.reduce((s, f) => s + f.lines, 0);
    const charSum = files.reduce((s, f) => s + f.chars, 0);

    out.push(`Extension: ${ext}`);
    out.push(`  Files: ${fileCount}`);
    out.push(`  Total Lines: ${lineSum}`);
    out.push(`  Total Characters: ${charSum}`);
    for (const f of files) {
      out.push(`    ${f.relPath}: ${f.lines} lines, ${f.chars} chars`);
    }

    totalFiles += fileCount;
    totalLines += lineSum;
    totalChars += charSum;
  }

  out.push('');
  out.push(`Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters`);

  process.stdout.write(out.join('\n') + '\n');
}

main();

