use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

fn count_lines(content: &[u8]) -> u64 {
    if content.is_empty() {
        return 0;
    }
    let newline_count = content.iter().filter(|&&b| b == b'\n').count() as u64;
    if content.last() == Some(&b'\n') {
        newline_count
    } else {
        newline_count + 1
    }
}

fn walk(dir: &Path, base: &Path, files: &mut Vec<(String, u64, u64)>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };

        let path = entry.path();

        if path.is_symlink() {
            continue;
        }

        let metadata = match fs::metadata(&path) {
            Ok(m) => m,
            Err(_) => continue,
        };

        if metadata.is_dir() {
            walk(&path, base, files);
        } else if metadata.is_file() {
            let content = match fs::read(&path) {
                Ok(c) => c,
                Err(_) => continue,
            };

            let chars = content.len() as u64;
            let lines = count_lines(&content);

            let rel = path
                .strip_prefix(base)
                .unwrap_or(&path)
                .to_string_lossy()
                .to_string();

            files.push((rel, lines, chars));
        }
    }
}

fn main() {
    let base = Path::new("<tmp>");

    let mut files: Vec<(String, u64, u64)> = Vec::new();
    walk(base, base, &mut files);

    let mut groups: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();

    for (rel_path, lines, chars) in &files {
        let p = Path::new(rel_path);
        let ext = p
            .extension()
            .map(|e| format!(".{}", e))
            .unwrap_or_else(|| String::new());
        groups
            .entry(ext)
            .or_insert_with(Vec::new)
            .push((rel_path.clone(), *lines, *chars));
    }

    for v in groups.values_mut() {
        v.sort_by(|a, b| a.0.cmp(&b.0));
    }

    let total_files = files.len() as u64;
    let total_lines: u64 = files.iter().map(|f| f.1).sum();
    let total_chars: u64 = files.iter().map(|f| f.2).sum();

    println!("=== File Tree Analysis ===");
    println!();

    for (ext, file_list) in &groups {
        let n_files = file_list.len() as u64;
        let n_lines: u64 = file_list.iter().map(|f| f.1).sum();
        let n_chars: u64 = file_list.iter().map(|f| f.2).sum();

        println!("Extension: {}", ext);
        println!("  Files: {}", n_files);
        println!("  Total Lines: {}", n_lines);
        println!("  Total Characters: {}", n_chars);

        for (rel_path, lines, chars) in file_list {
            println!("    {}: {} lines, {} chars", rel_path, lines, chars);
        }
    }

    println!();
    println!(
        "Total: {} files, {} lines, {} characters",
        total_files, total_lines, total_chars
    );
}

