            )),
        }
    }

    fn parse_literal(&mut self, literal: &str, value: Json) -> Result<Json, String> {
        let lc: Vec<char> = literal.chars().collect();
        for (i, &c) in lc.iter().enumerate() {
            if self.pos + i >= self.chars.len() || self.chars[self.pos + i] != c {
