    if (p->pos >= p->len) return;
    char c = p->s[p->pos];
    if (c == '"') {
        char tmp[512];
        jp_string(p, tmp, 512);
    } else if (c == '{' || c == '[') {
        int depth = 0;
        while (p->pos < p->len) {
            char ch = p->s[p->pos];
            if (ch == '{' || ch == '[') depth++;
            else if (ch == '}' || ch == ']') { depth--; if (depth == 0) { p->pos++; break; } p->pos++; }
            else if (ch == '"') { p->pos++; while (p->pos < p->len && p->s[p->pos] != '"') { if (p->s[p->pos] == '\\') p->pos++; p->pos++; } p->pos++; }
            else p->pos++;
        }
    } else if (c == 't' || c == 'f' || c == 'n') {
        while (p->pos < p->len && p->s[p->pos] != ',' && p->s[p->pos] != '}' && p->s[p->pos] != ']' && p->s[p->pos] != ' ' && p->s[p->pos] != '\n' && p->s[p->pos] != '\r' && p->s[p->pos] != '\t') p->pos++;
    } else {
        jp_number(p);
    }
}

int main(void) {
    const char *path = "<tmp>";
    long flen;
    char *data = read_file(path, &flen);
    if (!data) { fprintf(stderr, "Cannot open file\n"); return 1; }

    JP p = { data, 0, (int)flen };

    jp_ws(&p);
    if (p.pos >= p.len || p.s[p.pos] != '{') { fprintf(stderr, "Expected object\n"); return 1; }
    p.pos++;

    int num_nodes = 0, cap_nodes = 64;
    g_nodes = (char (*)[256])malloc((size_t)cap_nodes * 256);

    int num_edges = 0, cap_edges = 128;
    char **e_from = (char **)malloc((size_t)cap_edges * sizeof(char *));
    char **e_to   = (char **)malloc((size_t)cap_edges * sizeof(char *));
    double *e_w   = (double *)malloc((size_t)cap_edges * sizeof(double));

    while (1) {
        jp_ws(&p);
        if (p.pos >= p.len) break;
        if (p.s[p.pos] == '}') { p.pos++; break; }
        if (p.s[p.pos] == ',') { p.pos++; continue; }

        char key[256];
        if (!jp_string(&p, key, 256)) { fprintf(stderr, "Bad key\n"); return 1; }
        jp_ws(&p);
        if (p.pos >= p.len || p.s[p.pos] != ':') { fprintf(stderr, "Expected colon\n"); return 1; }
        p.pos++;
        jp_ws(&p);

        if (strcmp(key, "nodes") == 0) {
            if (p.pos >= p.len || p.s[p.pos] != '[') { fprintf(stderr, "Expected array\n"); return 1; }
            p.pos++;
            while (1) {
                jp_ws(&p);
                if (p.pos >= p.len) break;
                if (p.s[p.pos] == ']') { p.pos++; break; }
                if (p.s[p.pos] == ',') { p.pos++; continue; }
                if (num_nodes >= cap_nodes) {
                    cap_nodes *= 2;
                    g_nodes = (char (*)[256])realloc(g_nodes, (size_t)cap_nodes * 256);
                }
                if (!jp_string(&p, g_nodes[num_nodes], 256)) { fprintf(stderr, "Bad node string\n"); return 1; }
                num_nodes++;
            }
        } else if (strcmp(key, "edges") == 0) {
            if (p.pos >= p.len || p.s[p.pos] != '[') { fprintf(stderr, "Expected array\n"); return 1; }
            p.pos++;
            while (1) {
                jp_ws(&p);
                if (p.pos >= p.len) break;
                if (p.s[p.pos] == ']') { p.pos++; break; }
                if (p.s[p.pos] == ',') { p.pos++; continue; }
                if (p.pos >= p.len || p.s[p.pos] != '{') { fprintf(stderr, "Expected edge object\n"); return 1; }
                p.pos++;
                if (num_edges >= cap_edges) {
                    cap_edges *= 2;
                    e_from = (char **)realloc(e_from, (size_t)cap_edges * sizeof(char *));
                    e_to   = (char **)realloc(e_to,   (size_t)cap_edges * sizeof(char *));
                    e_w    = (double *)realloc(e_w,   (size_t)cap_edges * sizeof(double));
                }
                e_from[num_edges] = (char *)malloc(256);
                e_to[num_edges]   = (char *)malloc(256);
                e_from[num_edges][0] = '\0';
                e_to[num_edges][0]   = '\0';
                e_w[num_edges] = 0.0;

                while (1) {
                    jp_ws(&p);
                    if (p.pos >= p.len) break;
                    if (p.s[p.pos] == '}') { p.pos++; break; }
                    if (p.s[p.pos] == ',') { p.pos++; continue; }
                    char k2[256];
                    if (!jp_string(&p, k2, 256)) break;
                    jp_ws(&p);
                    if (p.pos >= p.len || p.s[p.pos] != ':') break;
                    p.pos++;
                    jp_ws(&p);
                    if (strcmp(k2, "from") == 0) jp_string(&p, e_from[num_edges], 256);
                    else if (strcmp(k2, "to") == 0) jp_string(&p, e_to[num_edges], 256);
                    else if (strcmp(k2, "weight") == 0) e_w[num_edges] = jp_number(&p);
                    else jp_skip_value(&p);
                }
                num_edges++;
            }
        } else {
            jp_skip_value(&p);
        }
    }

    free(data);

    /* Find source index */
    int src = -1;
    for (int i = 0; i < num_nodes; i++) {
        if (strcmp(g_nodes[i], "A") == 0) { src = i; break; }
    }
    if (src < 0) { fprintf(stderr, "Node A not found\n"); return 1; }

    /* Build adjacency list (undirected) */
    int *deg = (int *)calloc((size_t)num_nodes, sizeof(int));
    int **adj_v = (int **)malloc((size_t)num_nodes * sizeof(int *));
    double **adj_w = (double **)malloc((size_t)num_nodes * sizeof(double *));
    for (int i = 0; i < num_nodes; i++) {
        adj_v[i] = (int *)malloc((size_t)num_edges * sizeof(int));
        adj_w[i] = (double *)malloc((size_t)num_edges * sizeof(double));
    }

    for (int e = 0; e < num_edges; e++) {
        int fi = -1, ti = -1;
        for (int i = 0; i < num_nodes; i++) {
            if (strcmp(g_nodes[i], e_from[e]) == 0) fi = i;
            if (strcmp(g_nodes[i], e_to[e]) == 0) ti = i;
        }
        if (fi >= 0 && ti >= 0) {
            adj_v[fi][deg[fi]] = ti;
            adj_w[fi][deg[fi]] = e_w[e];
            deg[fi]++;
            adj_v[ti][deg[ti]] = fi;
            adj_w[ti][deg[ti]] = e_w[e];
            deg[ti]++;
        }
    }

    /* Dijkstra */
    double *dist = (double *)malloc((size_t)num_nodes * sizeof(double));
    int *vis = (int *)calloc((size_t)num_nodes, sizeof(int));
    for (int i = 0; i < num_nodes; i++) dist[i] = INFINITY;
    dist[src] = 0.0;

    for (int iter = 0; iter < num_nodes; iter++) {
        int u = -1;
        double md = INFINITY;
        for (int i = 0; i < num_nodes; i++) {
            if (!vis[i] && dist[i] < md) { md = dist[i]; u = i; }
        }
        if (u < 0) break;
        vis[u] = 1;
        for (int j = 0; j < deg[u]; j++) {
            int v = adj_v[u][j];
            if (!vis[v] && dist[u] + adj_w[u][j] < dist[v]) {
                dist[v] = dist[u] + adj_w[u][j];
            }
        }
    }

    /* Sort node indices alphabetically */
    int *order = (int *)malloc((size_t)num_nodes * sizeof(int));
    for (int i = 0; i < num_nodes; i++) order[i] = i;
    qsort(order, (size_t)num_nodes, sizeof(int), cmp_node_idx);

    /* Output */
    printf("=== Shortest Paths from A ===\n");
    printf("\n");
    for (int i = 0; i < num_nodes; i++) {
        int idx = order[i];
        printf("A -> %s: ", g_nodes[idx]);
        if (isinf(dist[idx])) {
            printf("unreachable");
        } else if (fabs(dist[idx] - (double)(long long)dist[idx]) < 1e-9) {
            printf("%lld", (long long)dist[idx]);
        } else {
            printf("%g", dist[idx]);
        }
        printf("\n");
    }

    /* Cleanup */
    for (int i = 0; i < num_nodes; i++) { free(adj_v[i]); free(adj_w[i]); }
    free(deg); free(adj_v); free(adj_w);
    for (int e = 0; e < num_edges; e++) { free(e_from[e]); free(e_to[e]); }
    free(e_from); free(e_to); free(e_w);
    free(dist); free(vis); free(order); free(g_nodes);

    return 0;
}
