enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

struct Parser {
    data: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { data: s.chars().collect(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.data.len() && self.data[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.data.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn expect(&mut self, c: char) -> Result<(), String> {
        self.skip_whitespace();
        if self.next() == Some(c) {
            Ok(())
        } else {
            Err(format!("Expected '{}'", c))
        }
    }

    fn parse_value(&mut self) -> Result<Json, String> {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Ok(Json::Str(self.parse_string()?)),
            Some('t') => {
                self.pos += 4;
                Ok(Json::Bool(true))
            }
            Some('f') => {
                self.pos += 5;
                Ok(Json::Bool(false))
            }
            Some('n') => {
                self.pos += 4;
                Ok(Json::Null)
            }
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.expect('"')?;
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => match self.next() {
                    Some('"') => s.push('"'),
                    Some('\\') => s.push('\\'),
                    Some('/') => s.push('/'),
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('b') => s.push('\u{0008}'),
                    Some('f') => s.push('\u{000C}'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            let c = self.next().unwrap();
                            let d = if c.is_ascii_digit() {
                                (c as u32) - ('0' as u32)
                            } else {
                                (c as u32) - ('a' as u32) + 10
                            };
                            code = code * 16 + d;
                        }
                        s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => return Err("Invalid escape".into()),
                },
                Some(c) => s.push(c),
                None => return Err("Unterminated string".into()),
            }
        }
        Ok(s)
    }

    fn parse_number(&mut self) -> Result<Json, String> {
        let start = self.pos;
        while self.pos < self.data.len() {
            let c = self.data[self.pos];
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s: String = self.data[start..self.pos].iter().collect();
        s.parse::<f64>().map(Json::Num).map_err(|e| e.to_string())
    }

    fn parse_array(&mut self) -> Result<Json, String> {
        self.expect('[')?;
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Ok(Json::Arr(arr));
        }
        loop {
            let v = self.parse_value()?;
            arr.push(v);
            self.skip_whitespace();
            match self.next() {
                Some(']') => break,
                Some(',') => continue,
                _ => return Err("Expected ',' or ']'".into()),
            }
        }
        Ok(Json::Arr(arr))
    }

    fn parse_object(&mut self) -> Result<Json, String> {
        self.expect('{')?;
        let mut obj = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Ok(Json::Obj(obj));
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string()?;
            self.expect(':')?;
            let val = self.parse_value()?;
            obj.push((key, val));
            self.skip_whitespace();
            match self.next() {
                Some('}') => break,
                Some(',') => continue,
                _ => return Err("Expected ',' or '}'".into()),
            }
        }
        Ok(Json::Obj(obj))
    }
}

fn get_obj_field(obj: &[(String, Json)], key: &str) -> Option<&Json> {
    obj.iter().find(|(k, _)| k == key).map(|(_, v)| v)
}

fn fmt_dist(d: f64) -> String {
    if d == f64::INFINITY {
