                                Some(Json::Str(s)) => s.clone(),
                                _ => panic!("Expected string for 'from'"),
                            };
                            let to = match get_obj_field(eobj, "to") {
                                Some(Json::Str(s)) => s.clone(),
                                _ => panic!("Expected string for 'to'"),
