                            (from, to, weight)
                        }
                        _ => panic!("Expected object in edges"),
                    })
                    .collect(),
                _ => panic!("Expected array for edges"),
            };

            (nodes, edges)
        }
        _ => panic!("Expected JSON object at top level"),
    };

    // Build adjacency list (undirected)
