    }
    for (from, to, weight) in &edges {
        adj.entry(from.clone())
            .or_insert_with(Vec::new)
            .push((to.clone(), *weight));
        adj.entry(to.clone())
            .or_insert_with(Vec::new)
            .push((from.clone(), *weight));
    }

    // Dijkstra's algorithm from "A"
