            if *i < s.len() && s.as_bytes()[*i] == b'}' {
                *i += 1;
                return Json::Obj(fields);
            }
            loop {
                skip_ws(s, i);
                if *i >= s.len() {
                    break;
                }
                let key = parse_string(s, i);
                skip_ws(s, i);
                if *i < s.len() && s.as_bytes()[*i] == b':' {
                    *i += 1;
                }
                let val = parse_json(s, i);
                fields.push((key, val));
                skip_ws(s, i);
                if *i < s.len() && s.as_bytes()[*i] == b',' {
                    *i += 1;
                } else if *i < s.len() && s.as_bytes()[*i] == b'}' {
                    *i += 1;
                    break;
                } else {
                    break;
                }
            }
            Json::Obj(fields)
        }
        b'[' => {
            *i += 1;
            let mut items = Vec::new();
            skip_ws(s, i);
            if *i < s.len() && s.as_bytes()[*i] == b']' {
                *i += 1;
                return Json::Arr(items);
            }
            loop {
                let val = parse_json(s, i);
                items.push(val);
                skip_ws(s, i);
                if *i < s.len() && s.as_bytes()[*i] == b',' {
                    *i += 1;
                } else if *i < s.len() && s.as_bytes()[*i] == b']' {
                    *i += 1;
                    break;
                } else {
                    break;
                }
            }
            Json::Arr(items)
        }
        b'"' => Json::Str(parse_string(s, i)),
        b't' => {
            *i += 4;
            Json::Bool(true)
        }
        b'f' => {
            *i += 5;
            Json::Bool(false)
        }
        b'n' => {
            *i += 4;
            Json::Null
        }
        _ => Json::Num(parse_number(s, i)),
    }
}

fn get_field<'a>(obj: &'a Json, key: &str) -> Option<&'a Json> {
    if let Json::Obj(fields) = obj {
        for (k, v) in fields {
            if k == key {
                return Some(v);
            }
        }
    }
    None
}

