static void strip_quotes(char *s) {
    size_t len = strlen(s);
    if (len >= 2 && s[0] == '"' && s[len - 1] == '"') {
        s[len - 1] = '\0';
        memmove(s, s + 1, len - 2);
        s[len - 2] = '\0';
    }
}

static void format_int_comma(long long v, char *buf, int size) {
    if (size <= 0) return;
    if (v < 0) {
        if (size > 1) snprintf(buf, size, "-");
        else { buf[0] = '\0'; return; }
        v = -v;
        buf++;
        size--;
    }
    char tmp[32];
    int len = snprintf(tmp, sizeof(tmp), "%lld", v);
    int pos = 0;
    int cnt = 0;
    for (int i = len - 1; i >= 0; i--) {
        if (pos >= size - 1) break;
        buf[pos++] = tmp[i];
        cnt++;
        if (cnt % 3 == 0 && i > 0 && pos < size - 1) {
            buf[pos++] = ',';
        }
    }
    int l = 0, r = pos - 1;
    while (l < r) {
        char t = buf[l]; buf[l] = buf[r]; buf[r] = t;
        l++; r--;
    }
    buf[pos] = '\0';
}

static void format_avg_comma(double val, char *buf, int size) {
    if (size <= 0) return;
    long long v = (long long)(val * 100.0 + 0.5);
    int neg = 0;
    if (v < 0) { neg = 1; v = -v; }
    long long intpart = v / 100;
