    int pos = 0;
    if (neg && pos < size - 1) { buf[pos++] = '-'; }

    int cnt = 0;
    for (int i = len - 1; i >= 0; i--) {
        if (pos >= size - 5) break;
        buf[pos++] = tmp[i];
        cnt++;
        if (cnt % 3 == 0 && i > 0 && pos < size - 5) {
            buf[pos++] = ',';
        }
    }
    int l = neg ? 1 : 0;
    int r = pos - 1;
    while (l < r) {
        char t = buf[l]; buf[l] = buf[r]; buf[r] = t;
        l++; r--;
    }
    snprintf(buf + pos, size - pos, ".%02lld", decpart);
}

